const $=s=>document.querySelector(s);const symbol=n=>`<span class="symbol" aria-hidden="true">${n}</span>`;
const uiIcon=name=>window.YolkIcons?.icon(name)||'';
const navIcon={market:'map',demand:'location_on',targets:'bookmark_added',supply:'local_gas_station',criteria:'tune',feed:'history'};
const num=(n,dec=0)=>new Intl.NumberFormat(Y.lang==='en'?'en-GB':'th-TH',{maximumFractionDigits:dec,minimumFractionDigits:dec}).format(n);
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').classList.remove('visible'),3600)}
const navItems=[['market','ภาพรวมประเทศ','Market map'],['demand','Demand · ไข่แดง','Demand · Yolks'],['targets','ทำเลที่เล็งไว้','Shortlist'],['supply','สาขา / Supply','Branches'],['criteria','เกณฑ์','Criteria'],['feed','ความเคลื่อนไหว','Activity']];
const tabTitle=r=>{let n=navItems.find(x=>x[0]===r);return n?tr(n[1],n[2]):r==='place'?tr('รายละเอียดทำเล','Location detail'):r==='poi'?tr('จัดการสาขา','Branch editor'):r==='team'?tr('ทีมและสิทธิ์','Team & roles'):tr('การแจ้งเตือน','Inbox')};
function pendingSupplyBadge(){if(Y.pointState!=='ready')return '';const n=Y.pois.filter(x=>!x.archived&&(x.relation==='unverified'||x.status==='pending')).length;if(!n)return '';const label=tr('รอตรวจสอบ '+n+' รายการ',n+' records to verify');return `<span class="nav-count" title="${escapeHTML(label)}" aria-label="${escapeHTML(label)}">U ${num(n)}</span>`;}
function header(){
 navIcon.supply=Y.industry==='fuel'?'local_gas_station':'store';
 const settingsOpen=!!$('#header').querySelector?.('[data-header-settings]')?.open;
 const languageFocused=settingsOpen&&document.activeElement?.matches?.('[data-action="language"]');
 document.documentElement.lang=Y.lang;
 $('#sidebar').innerHTML=`<span class="landometer-identity-img sidebar-identity logo-contrast"><img src="assets/landometer-logo-horizontal-v12-889.png" width="889" height="244" alt="Landometer"></span><a class="yolk-brand" href="#market"><span>CityMETER:</span><strong>${YolkIcons.yolkWordmark()}</strong></a><p class="brand-line">${tr('ไข่แดงที่ Demand เข้มข้น<br>เริ่มตรงนี้ แล้วมองหาช่องว่างของสาขา','Concentrated demand.<br>Find the yolk, then the supply gap.')}</p><a class="workspace" href="#team"><span class="workspace-mark">${uiIcon('groups')}</span><div><strong>${escapeHTML(YolkBrands.displayName(Y.ownBrandId,ownBrandName()))+' · '+tr('ทีมขยายสาขา','Expansion team')}</strong><small>Enterprise · 10 ${tr('สมาชิก','members')}</small></div></a><nav aria-label="${tr('เมนูหลัก','Main navigation')}">${navItems.map(([id,th,en])=>`<a class="${Y.route===id?'active':''}" href="#${id}" ${Y.route===id?'aria-current="page"':''}>${uiIcon(navIcon[id])}<span class="nav-label">${tr(th,en)}</span>${id==='supply'?pendingSupplyBadge():''}</a>`).join('')}</nav>`;
 $('#header').innerHTML=`<a class="compact-brand" href="#market" aria-label="CityMETER: Yolk — ${tr('หาไข่แดง','Find the yolk')}">${YolkIcons.yolkWordmark()}<span class="compact-brand-tagline">CityMETER · ${tr('หาไข่แดง','Find the yolk')}</span></a><div class="crumb"><span>${escapeHTML(YolkBrands.displayName(Y.ownBrandId,ownBrandName()))+' · '+tr('ทีมขยายสาขา','Expansion team')}</span><span>/</span><strong>${tabTitle(Y.route)}</strong></div><div class="header-tools"><button class="inbox-button shell-action" data-action="inbox" aria-label="${tr('แจ้งเตือน','Notifications')}${unreadCount()?' · '+unreadCount():''}">${uiIcon('notifications')}<span class="shell-action-label">${tr('เตือน','Inbox')}</span>${unreadCount()?`<span class="count-badge">${unreadCount()}</span>`:''}</button><details class="header-settings" data-header-settings ${settingsOpen?'open':''}><summary class="shell-action">${uiIcon('menu')}<span class="shell-action-label">${tr('เมนู','Menu')}</span></summary><div class="header-menu-panel"><span class="landometer-identity-img header-identity logo-contrast"><img src="assets/landometer-logo-horizontal-v12-889.png" width="889" height="244" alt="Landometer"></span><strong class="header-menu-title">${tr('ตั้งค่าการใช้งาน','Your settings')}</strong><p class="header-menu-note">${tr('ต้นแบบในเครื่อง · Snapshot สาธารณะ','Local prototype · Public snapshot')}</p>${YolkTheme.renderControl(Y.lang)}<div class="header-menu-language"><span>${tr('ภาษา','Language')}</span><button class="language-toggle" data-action="language" aria-label="${tr('Switch to English','เปลี่ยนเป็นภาษาไทย')}">${Y.lang==='th'?'English':'ไทย'}</button></div><label class="person-selector"><span>${tr('ทดลองใช้ในบทบาท','Try a team role')}</span><select id="actor-select">${PEOPLE.map(p=>`<option value="${p.id}" ${p.id===Y.actor?'selected':''}>${person(p.id)} · ${p.role}</option>`).join('')}</select></label><a class="header-team-link" href="#team">${uiIcon('groups')}${tr('ทีมและสิทธิ์','Team & roles')}</a></div></details></div>`;
 const mobileLabels={market:['ภาพรวม','Market'],demand:['Demand','Demand'],targets:['เล็งไว้','Saved'],supply:['สาขา','Branches'],criteria:['เกณฑ์','Criteria'],feed:['ประวัติ','Activity']};
 $('#mobile-nav').innerHTML=navItems.map(([id])=>`<a class="${Y.route===id?'active':''}" href="#${id}" ${Y.route===id?'aria-current="page"':''}>${uiIcon(navIcon[id])}<span>${tr(...mobileLabels[id])}</span></a>`).join('');
 document.title=tabTitle(Y.route)+' · CityMETER: Yolk';
 if(languageFocused)$('#header').querySelector?.('[data-action="language"]')?.focus?.();
}
function scoreText(a){return YolkDecisions.rankText(a)}

function placeRow(a,index){let saved=!!Y.targets[a.id]&&!Y.targets[a.id].archived;return `<article class="place-row ${Y.selected===a.id?'selected':''}" data-place="${a.id}"><div class="row-top"><span class="rank">${String(index+1).padStart(2,'0')}</span><div class="location-main"><button class="location-title" data-action="place" data-id="${a.id}">${escapeHTML(areaName(a.id))}</button><small>${escapeHTML(provinceName(a.province))} · ${tr(a.geoType==='khwaeng'?'แขวง':'อปท.',a.geoType==='khwaeng'?'Khwaeng':'Local authority')}</small></div><div class="score">${scoreText(a)}<small>${YolkDecisions.rankLabel()}</small></div></div><div class="row-tags">${yolkBadge(a)}<span class="row-tier">${YolkDecisions.tierText(a)}</span>${a.reviewCandidate?`<span class="tag wait">${tr('รอตรวจ · ยังไม่ผ่านเกณฑ์ครบ','Review · not yet fully eligible')}</span>`:a.eligible&&!a.pattern?`<span class="tag">${tr('Demand ผ่านเกณฑ์','Demand qualifies')}</span>`:''}<span class="small">${tr('เรา','Own')} ${supplyCountText(a.supply,'own')} · ${tr('คู่แข่ง','Rivals')} ${supplyCountText(a.supply,'competitor')}${a.supply.unverified?` · ${tr('รอตรวจ','Pending')} ${a.supply.unverified}`:''}</span></div>${window.YolkSupplyCompare.panel(a,Y.criteria,true)}<div class="place-row-footer"><button class="btn view-details" data-action="place" data-id="${a.id}">${uiIcon('location_on')}${tr('ดูรายละเอียด','View details')}</button><button class="btn ${saved?'saved':'soft'} small-button" data-action="target" data-id="${a.id}" ${!canEdit()?'disabled':''}>${uiIcon(saved?'bookmark_added':'bookmark_add')}${saved?tr('เล็งไว้แล้ว','Saved'):tr('เล็งทำเลนี้','Shortlist')}</button></div></article>`}
function yolkBadge(a){return a.demand===true?`<span class="yolk-badge">${window.YolkIcons?.yolkIcon()||''}${tr('Yolk · ไข่แดง','Yolk · High demand')}</span>`:`<span class="demand-status">${a.demand===null?tr('Demand ยังไม่ชัด','Demand unresolved'):tr('Demand ยังไม่สูง','Demand below threshold')}</span>`}
function mapStats(rows){return P.map(p=>{let areas=rows.filter(a=>a.province===p.code),eligible=areas.filter(a=>a.eligible),yolks=areas.filter(a=>a.demand===true),visibleYolks=yolks.filter(a=>Y.mapScope==='all'||a.eligible);return {...p,areas,eligible,yolks,visibleYolks,best:visibleYolks.length?Math.max(...visibleYolks.map(a=>a.score)):null,missing:visibleYolks.length===0&&areas.some(a=>a.demand===null)}})}
function provinceSummary(s){return `${provinceName(s.code)} · ${num(s.yolks.length)} ${tr('ไข่แดงทั้งหมด','Yolks in total')} · ${num(s.visibleYolks.length)} ${tr('ไข่แดงในมุมมองนี้','Yolks in this view')} · ${num(s.eligible.length)} ${tr('ทำเลผ่านเกณฑ์ทีม','locations match team criteria')}${s.missing?' · '+tr('ข้อมูล Demand บางส่วนยังไม่ครบ','Some Demand evidence unresolved'):''}`}
function choropleth(stats){return `<svg id="thai-map" viewBox="0 0 640 900" aria-label="${tr('แผนที่ 77 จังหวัด แสดงไข่แดงที่ Demand สูง','77-province map of high-demand Yolk locations')}" role="group"><defs><pattern id="unknown-hatch" width="7" height="7" patternUnits="userSpaceOnUse"><rect width="7" height="7" fill="var(--yl-no-data)"/><path d="M-1 1 1-1M0 7 7 0M6 8 8 6" stroke="var(--yl-border-strong)" stroke-width="1"/></pattern></defs>${stats.map(s=>`<path class="province ${Y.province===s.code?'selected':''}" d="${s.path}" fill-rule="evenodd" fill="${s.missing?'url(#unknown-hatch)':s.best===null?'var(--no-result)':`var(--yl-yolk-map-${s.best>=99?3:s.best>=95?2:1})`}" data-action="province" data-code="${s.code}" tabindex="0" role="button" aria-label="${escapeHTML(provinceSummary(s))}"><title>${escapeHTML(provinceSummary(s))}</title></path>`).join('')}</svg>`}
// Personal map drilldown filters; no workspace mutation or criteria change.
function mapNavigation(){return window.YolkWorkspaceMap?.getNavigation?.()||{level:'country'};}
function inMapArea(area){return window.YolkWorkspaceMap?.areaMatchesNavigation?.(area)??true;}
function inMapPoi(poi){return window.YolkWorkspaceMap?.poiMatchesNavigation?.(poi)??true;}
function inPoiArea(poi,id){return window.YolkWorkspaceMap?.poiMatchesArea?.(poi,id)??poi.area===id;}
function mapNavigationTitle(){const path=mapNavigation();return path.level==='location'?areaName(path.areaId):path.level==='district'?(path.districtName||path.districtId):path.level==='province'?provinceName(path.provinceCode):tr('ทำเลที่ควรดูต่อ','Locations to explore');}
function market(){
 let all=evaluate(),stats=mapStats(all),passing=all.filter(a=>a.eligible),review=all.filter(a=>a.reviewCandidate),selected=Y.province?stats.find(p=>p.code===Y.province):null;
 let viewAreas=(selected?selected.areas:all).filter(inMapArea);let q=Y.listQuery.toLowerCase(),list=(selected?viewAreas:viewAreas.filter(a=>a.eligible||a.reviewCandidate)).filter(a=>(areaName(a.id)+' '+provinceName(a.province)).toLowerCase().includes(q));
 Y.marketPage=Math.max(0,Math.min(Y.marketPage,Math.ceil(list.length/12)-1));let offset=Y.marketPage*12;
 return `<div class="page-head"><div><h1><span class="yolk-title">${window.YolkIcons?.yolkIcon()||''}${tr('หาไข่แดงให้เจอ','Find the yolk.')}</span> <span class="market-goal">${tr('ขยายตลาดให้ตรงจุด','Grow your market.')}</span></h1><p>${tr('ไข่แดง คือทำเลที่ Demand เข้มข้น แล้วค่อยดูช่องว่างของสาขาเพื่อเลือกที่ไปต่อ','A Yolk is a place with concentrated demand. Compare branch supply to decide where to explore next.')}</p></div><a class="btn primary" href="#criteria">${uiIcon('tune')}${tr('ปรับเกณฑ์ของทีม','Adjust team criteria')}</a></div>
 <div class="market-status"><span>${escapeHTML(ownBrandName())+' · '+industryName()} · v${Y.criteria.version}</span><span>${num(all.filter(a=>a.demand===true).length)} ${tr('ไข่แดงจาก Demand','Demand Yolks')}</span><span><strong>${num(passing.length)}</strong> ${tr('อยู่ในระดับที่เลือก','in selected Demand levels')}</span><span>${num(review.length)} ${tr('ทำเลรอตรวจข้อมูลก่อนยืนยันผล','locations need evidence review before confirmation')}</span><span>${tr('เทียบทั้งประเทศ · กทม. ใช้แขวง / ต่างจังหวัดใช้ อปท.','One nationwide benchmark · Bangkok khwaeng / upcountry local authorities')}</span></div>
 <div class="national-layout"><aside class="national-ranking"><div class="ranking-head"><h2 id="province-results" tabindex="-1">${escapeHTML(mapNavigationTitle())}</h2>${selected?`<p class="province-counts">${num(viewAreas.filter(a=>a.demand===true).length)} ${tr('ไข่แดงทั้งหมด','Yolks in total')} · ${num(viewAreas.filter(a=>a.demand===true&&(Y.mapScope==='all'||a.eligible)).length)} ${tr('ไข่แดงในมุมมองนี้','Yolks in this view')} · ${num(viewAreas.filter(a=>a.eligible).length)} ${tr('ทำเลผ่านเกณฑ์ทีม','locations match team criteria')}</p>`:''}<p>${Y.criteria.rankingMode==='weighted'?tr('ทำเลที่ผ่านเกณฑ์ เรียงตามน้ำหนักที่ทีมเลือก','Eligible locations, ordered by team weights'):Y.criteria.rankingMode==='context'?tr('ผ่านเกณฑ์ → Tier → เส้นทางสัญญาณที่ยืนยันได้','Eligibility → tier → confirmed path strength'):tr('ผ่าน Demand → ระดับความเข้ม → สัญญาณที่ผ่าน','Demand eligibility → tier → passing signals')}</p></div><label class="search">${uiIcon('search')}${tr('ค้นหา','Search')}<input id="location-search" value="${escapeHTML(Y.listQuery)}" aria-label="${tr('ค้นหาทำเลหรือจังหวัด','Search location or province')}" placeholder="${tr('ทำเล / จังหวัด','Location / province')}"></label><div class="ranking-list">${list.length?list.slice(offset,offset+12).map((a,i)=>placeRow(a,offset+i)).join(''):`<div class="empty"><h3>${tr('ยังไม่มีทำเลตรงเกณฑ์','No matching locations')}</h3><a href="#criteria" class="btn">${tr('ดูเกณฑ์','View criteria')}</a></div>`}</div><div class="pagination"><button class="btn small-button" data-action="market-prev" ${Y.marketPage===0?'disabled':''}>${tr('ก่อนหน้า','Previous')}</button><span>${num(list.length)} ${tr(selected?'ทำเลในพื้นที่ที่เลือก':'ทำเลที่แสดง (ผ่านเกณฑ์ + รอตรวจ)',selected?'locations in selected area':'shown (confirmed + review)')} · ${Y.marketPage+1}/${Math.max(1,Math.ceil(list.length/12))}</span><button class="btn small-button" data-action="market-next" ${offset+12>=list.length?'disabled':''}>${tr('ถัดไป','Next')}</button></div><p class="footline">${tr('บริบทพื้นที่จริง · เกณฑ์ proxy เป็นสมมติฐาน ไม่ใช่ลูกค้าหรือยอดขายจริง','Observed area context · Proxy thresholds are hypotheses, not actual customers or sales.')}</p></aside></div>`
}

function changeView(e){return e.changes.map(c=>`<div class="change-line"><span>${fieldNames[c.field]?tr(...fieldNames[c.field]):escapeHTML(c.field)}</span><div><del>${escapeHTML(displayValue(c.before,c.field))}</del><span class="change-arrow">→</span><strong>${escapeHTML(displayValue(c.after,c.field))}</strong></div></div>`).join('')}
function feed(events,{limit=6,links=true}={}){if(!events.length)return `<div class="feed-empty">${tr('ยังไม่มีการเปลี่ยนแปลงในหน้านี้','No changes in this context yet')}</div>`;return `<ol class="context-feed">${events.slice(0,limit).map(e=>`<li class="feed-item ${e.recipients.includes(Y.actor)&&!(Y.read[Y.actor]||[]).includes(e.id)?'unread':''}"><span class="feed-avatar">${escapeHTML(person(e.actor).slice(0,1))}</span><div class="feed-body"><div class="feed-byline"><strong>${escapeHTML(person(e.actor))}</strong><span>${eventTitle(e)}</span>${e.recipients.includes(Y.actor)&&!(Y.read[Y.actor]||[]).includes(e.id)?`<span class="unread-label">${tr('ใหม่','New')}</span>`:''}<time datetime="${e.at}">${eventTime(e.at)}</time></div>${e.meta.ownBrandId?`<p class="feed-context">${escapeHTML(e.meta.ownBrandName||e.meta.ownBrandId)} · ${escapeHTML(e.meta.industryName?.[Y.lang]||e.meta.industry)} · ${escapeHTML(e.meta.supplyScope)}</p>`:''}${e.meta.sample?`<small>${tr('ตัวอย่างเหตุการณ์เริ่มต้น','Seed example event')}</small>`:''}${e.entity==='place'?`<p class="feed-context">${escapeHTML(areaName(e.entity_id))} · ${escapeHTML(provinceName(AREAS.find(a=>a.id===e.entity_id)?.province))}</p>`:e.entity==='supply'?`<p class="feed-context">${escapeHTML(branchName(Y.pois.find(p=>p.id===e.entity_id)||{name:e.entity_id}))}</p>`:''}${changeView(e)}<div class="feed-receipt"><span>${tr('แจ้งสมาชิกอื่น','Notified other members')} ${e.recipients.length} ${tr('คน','people')} · ${tr('ในต้นแบบ','in this demo')}</span>${links?`<button class="quiet-link" data-action="event-context" data-id="${e.id}">${tr('เปิดบริบท','Open context')} →</button>`:''}</div></div></li>`).join('')}</ol>`}
function numberControl(key,th,en,min=1,max=100){return `<div class="field"><label for="c-${key}">${tr(th,en)}</label><input id="c-${key}" data-criterion="${key}" type="number" min="${min}" max="${max}" value="${draft[key]}"></div>`}
function metricList(ids,p=95){return `<ul class="metric-list">${ids.map(id=>{let m=METRIC_INDEX[id];return `<li><span>${tr(m.th,m.en)}<small>${tr(m.unitTh,m.unitEn)}</small></span><span class="metric-cutoff" data-cutoff-id="${id}">P${p} ≥ ${num(cutoff(id,p),2)}</span></li>`}).join('')}</ul>`}
function metricReason(m){let r={crosswalk:['รอเชื่อมข้อมูลกับขอบเขตพื้นที่ให้ครบ','Area crosswalk and coverage pending'],size:['รอยืนยันนิยามขนาดใหญ่และเชื่อมพื้นที่','Size definition and area crosswalk pending'],health:['รอยืนยันแหล่งข้อมูลและนิยามขนาด','Source and size definition pending'],traffic:['รอยืนยันช่วงเวลาวัดและขอบเขตถนน','Measurement period and road coverage pending']};return m.ready?tr('มีข้อมูลให้ทดลอง · ยังไม่เปิดใช้','Available to preview · off by default'):tr(...r[m.reason])}
function metricPicker(metricId,attrs){const uid='picker-'+attrs.replace(/[^a-zA-Z0-9]+/g,'-');const metric=METRIC_INDEX[metricId],copy=metric.display,datasets=[...new Set(METRICS.filter(m=>m.ready).map(m=>m.dataset))];return `<div class="metric-picker"><div class="field"><label for="${uid}-dataset">${tr('ชุดข้อมูล CityMETER','CityMETER dataset')}</label><select id="${uid}-dataset" data-picker-dataset ${attrs}>${datasets.map(id=>{const d=METRICS.find(m=>m.dataset===id).display;return `<option value="${escapeHTML(id)}" ${metric.dataset===id?'selected':''}>${escapeHTML(tr(d.datasetTH,d.datasetEN))}</option>`}).join('')}</select></div><div class="field"><label for="${uid}-metric">${tr('ตัววัด / สูตรที่มีข้อมูล','Available metric / formula')}</label><select id="${uid}-metric" data-picker-metric ${attrs}>${METRICS.filter(m=>m.ready&&m.dataset===metric.dataset).map(m=>`<option value="${m.id}" ${m.id===metricId?'selected':''}>${tr(m.th,m.en)}</option>`).join('')}</select></div><details class="formula-note"><summary>${tr('สูตร หน่วย และความครอบคลุม','Formula, unit and coverage')} · ${tr(metric.unitTh,metric.unitEn)}</summary><p><strong>${escapeHTML(tr(copy.formulaTH,copy.formulaEN))}</strong><br>${tr('หน่วย','Unit')}: ${escapeHTML(tr(metric.unitTh,metric.unitEn))}<br>${escapeHTML(tr(copy.periodTH,copy.periodEN))} · ${escapeHTML(tr(copy.evidenceTH,copy.evidenceEN))}<br>${escapeHTML(tr(copy.meaningTH,copy.meaningEN))}<br>${escapeHTML(tr(copy.coverageTH,copy.coverageEN))}</p><p>${tr('ฟิลด์ต้นทางที่ใช้','Qualified source fields')}: <code>${escapeHTML(copy.sourceQualifiedFields.join(' · '))}</code></p></details></div>`}
function advancedDemandControls(){const primary=primaryIds(draft),activity=activityIds(draft);const groups=draft.paths?[['primary',tr(Y.industry==='nonbank'?'ฐานประชากรอายุ 20–64 ปี':'ฐานประชากร','Population context'),'buildingEnabled'],['activity',tr('บริบทคนงานที่ต้นทางรายงาน','Reported workplace context'),'activityEnabled']].filter(g=>g[0]!=='activity'||draft.paths.some(p=>p.id.startsWith('workplace'))):[];return `<section class="section demand-section"><div class="block-title"><h2>1. Demand</h2><span class="tag">${escapeHTML(ownBrandName())}</span></div><p class="lead">${tr('เลือกชุดข้อมูลและตัววัดที่มีค่าจริง สูตรคำนวณจากค่าต้นทางที่ผูก UUID เท่านั้น','Choose datasets and actual available metrics. Formulas use source fields joined by reporting UUID only.')}</p><p class="rule-caption">${tr('ค่าเริ่มต้นของธุรกิจเป็นสมมติฐานเพื่อศึกษาต่อ ปรับแยกตามแบรนด์; proxy ผ่านเกณฑ์ไม่ยืนยันยอดซื้อ การกู้ หรือความเสี่ยง','Industry presets are adjustable research hypotheses, saved per brand. A qualifying proxy does not confirm purchases, borrowing or risk.')}</p>${draft.paths?groups.map(([group,label,toggle])=>`<div class="signal-group"><label class="signal-toggle"><input type="checkbox" data-toggle="${toggle}" ${draft[toggle]?'checked':''}><strong>${label}</strong></label>${draft.paths.map((path,index)=>({path,index})).filter(({path})=>group==='activity'?path.id.startsWith('workplace'):!path.id.startsWith('workplace')).map(({path,index})=>`<fieldset class="path-rule"><legend>Tier ${path.tier} · ${tr('ทุกข้อผ่าน (AND)','All conditions pass (AND)')}</legend>${path.all.map((condition,conditionIndex)=>`<div class="path-condition">${metricPicker(condition.metric,`data-path-index="${index}" data-condition-index="${conditionIndex}"`)}<div class="field"><label for="path-${index}-${conditionIndex}-percentile">${tr('ผ่านเมื่อ ≥ Percentile','Passes at ≥ percentile')}</label><input id="path-${index}-${conditionIndex}-percentile" type="number" min="1" max="100" value="${condition.percentile}" data-path-percentile data-path-index="${index}" data-condition-index="${conditionIndex}"></div></div>`).join('')}</fieldset>`).join('')}</div>`).join(''):`<div class="signal-group"><label class="signal-toggle"><input type="checkbox" data-toggle="buildingEnabled" ${draft.buildingEnabled?'checked':''}><strong>${tr('สัญญาณกลุ่มหลัก','Primary signal group')}</strong></label><div class="inline-fields">${numberControl('buildingP1','Tier 1: ทุกข้อ ≥ P','Tier 1: all metrics ≥ P')}${numberControl('buildingP2','Tier 2/3: เกณฑ์ ≥ P','Tier 2/3: threshold P')}</div>${primary.map((id,i)=>metricPicker(id,`data-core-group="building" data-core-index="${i}"`)).join('')}<p>${tr('Tier 2 ทุกข้อผ่าน · Tier 3 อย่างน้อยหนึ่งข้อผ่าน','Tier 2: all pass · Tier 3: at least one passes')}</p></div><div class="signal-group"><label class="signal-toggle"><input type="checkbox" data-toggle="activityEnabled" ${draft.activityEnabled?'checked':''}><strong>${tr('สัญญาณกลุ่มสนับสนุน','Supporting signal group')}</strong></label>${numberControl('activityP','แต่ละข้อผ่านเมื่อ ≥ P','Each metric passes at ≥ P')}<div class="tier-inputs">${[1,2,3].map(n=>numberControl('activityT'+n,'Tier '+n+': อย่างน้อย (ข้อ)','Tier '+n+': at least (hits)',1,25)).join('')}</div>${activity.map((id,i)=>metricPicker(id,`data-core-group="activity" data-core-index="${i}"`)).join('')}</div>`}<details class="metric-catalog"><summary>${tr('เพิ่มตัววัดจริงเป็นเส้นทาง Tier 3 (OR)','Add an actual metric as a Tier 3 path (OR)')}</summary>${METRICS.filter(m=>m.ready&&!enabledMetricIds({...draft,extraMetrics:[]}).includes(m.id)).map(m=>`<label class="catalog-row"><input type="checkbox" data-extra="${m.id}" ${draft.extraMetrics.includes(m.id)?'checked':''}><span><strong>${tr(m.th,m.en)}</strong><small>${escapeHTML(m.dataset)} · ${tr(m.unitTh,m.unitEn)} · <code>${escapeHTML(m.formula)}</code></small></span></label>`).join('')}${numberControl('extraP','ตัววัดเพิ่มเติมผ่านเมื่อ ≥ P','Additional metric passes at ≥ P')}</details><p class="footline">${tr('Percentile.INC ฐาน 7,954 หน่วย ค่าที่มีเท่านั้น · ไม่มีข้อมูลไม่ใช่ศูนย์ · ข้อมูล proxy ไม่ใช่ลูกค้าจริง','PERCENTILE.INC over known values in the 7,954-unit universe. Missing is not zero; proxies are not measured customers.')}</p></section>`}

function demandControls(){return YolkSimpleCriteria.demand(advancedDemandControls())}

function supplyControls(){
 const relative=draft.supplyMode==='relative',api=window.YolkRelativeSupply,metricId=draft.supplyDenominatorId||(Y.industry==='fuel'?'gfa':'population'),unit=(api?.unitLabel(metricId,Y.lang)||'').split(' · ')[0],cal=draft.supplyCalibration;
 const rateControl=(key,id,label)=>{const role=key==='ownRateHigh'?'own':'competitor',value=draft[key],seed=cal?.[role]?.threshold??Y.criteria[key],reference=Number.isFinite(seed)&&seed>0?seed:1,max=reference<.2?1:Math.max(1,Math.ceil(reference*4));return `<div class="field"><label for="${id}">${escapeHTML(label)}</label><input id="${id}" data-criterion="${key}" data-supply-rate data-rate-unit="${escapeHTML(unit)}" data-range-step="${reference<.01?.0001:reference<.1?.001:.01}" type="number" min="${Math.min(.001,reference/10)}" max="${max}" step="any" value="${value}"></div>`};
 const seedNote=cal?['own','competitor'].map(role=>{const part=cal[role];return `<li><strong>${role==='own'?escapeHTML(ownBrandName()):tr('คู่แข่ง','Competitors')}</strong> · ${part?.method==='median_national_known_positive_exact_rates'?tr('ค่ากลางอัตราที่พบจริง','Median observed positive rate'):part?.method==='hypothesis_insufficient_sample'?tr('สมมติฐานเริ่มต้น · ตัวอย่างยังไม่พอ','Exploratory default · insufficient sample'):tr('ค่าตั้งต้นจากข้อมูลที่มี','Seeded from available data')} · ${tr('ตัวอย่างที่ใช้','Sample')} ${part?.n??0} ${tr('ทำเล','locations')}</li>`}).join(''):'';
 return `<section class="section supply-section"><div class="block-title"><h2>${uiIcon('shield')}${tr('2. ดูช่องว่างสาขา','2. Compare branch supply')}</h2><span class="tag blue">${relative?tr('เทียบขนาดตลาด','Market-size rate'):tr('จำนวนสาขา','Branch count')}</span></div><p class="lead">${tr('โล่คือสาขาเรา ดาบคือคู่แข่ง เทียบด้วยหน่วยเดียวกัน แล้วเลือกว่าจะให้น้ำหนักช่องว่างฝั่งไหน','Shield means our stores; swords mean competitors. Compare the same units and choose which gap should lead.')}</p><p class="supply-cutoff-explainer">${tr('ปรับ Supply เพื่อเรียงทำเล จำนวนไข่แดงและระดับ Demand คงเดิม คู่แข่งมากไม่ได้แปลว่าทำเลไม่ดี','Supply changes the order, not the Demand set or tiers. Many competitors do not automatically make a location unattractive.')}</p><fieldset class="supply-mode"><legend>${tr('วิธีวัด Supply','How to measure supply')}</legend>${[['relative','สาขาเทียบขนาดตลาด','Branches / market size','tune'],['count','จำนวนสาขา','Branch count','store']].map(([mode,th,en,icon])=>`<label class="supply-mode-option"><input type="radio" name="supply-mode" value="${mode}" ${mode===(relative?'relative':'count')?'checked':''}>${uiIcon(icon)}<strong>${tr(th,en)}</strong>${mode==='relative'?`<small>${tr('แนะนำ','Recommended')}</small>`:''}</label>`).join('')}</fieldset>${relative?`<details class="supply-denominator"><summary>${uiIcon('tune')}${tr('เปลี่ยนฐานตลาด','Change market-size denominator')}</summary><label for="supply-denominator">${tr('เทียบกับฐานตลาด','Market-size denominator')}</label><select id="supply-denominator">${(api?.catalog||[]).map(m=>`<option value="${m.id}" ${m.id===metricId?'selected':''}>${escapeHTML(Y.lang==='en'?m.nameEn:m.nameTh)}</option>`).join('')}</select><p class="rule-caption">${escapeHTML(unit)} · ${tr('เปลี่ยนฐานแล้ว ระบบตั้งเกณฑ์ใหม่ในแบบร่างให้ ต้องกดใช้กับทีมจึงบันทึก','Changing the denominator reseeds draft thresholds. Apply to team to save.')}</p></details><div class="inline-fields">${rateControl('ownRateHigh','own-rate',YolkBrands.displayName(Y.ownBrandId,ownBrandName())+' '+tr('จุดเทียบช่องว่าง','Gap reference'))}${rateControl('competitorRateHigh','competitor-rate',tr('จุดเทียบช่องว่างคู่แข่ง','Competitor gap reference'))}</div><details class="formula-note"><summary>${uiIcon('help')}${tr('สูตรและที่มาของค่าเริ่มต้น','Formula and initial thresholds')}</summary><p>${tr('อัตรา = จำนวนสาขา ÷ ค่าฐานตลาด × หน่วยที่แสดง ไม่ใช้ Percentile เป็นตัวหาร','Rate = branch count ÷ raw market-size value × displayed unit. A percentile is never the denominator.')}</p><ul>${seedNote}</ul><p>${tr('ค่าเริ่มต้นใช้ค่ากลางของอัตรามากกว่าศูนย์ที่ยืนยันได้ทั่วประเทศ แยกเราและคู่แข่ง ต้องมีอย่างน้อย 5 ทำเล; หากไม่พอ ทดลองเริ่มที่ 1 สาขาต่อหน่วย ยังไม่ใช่เกณฑ์ที่สอบเทียบยอดขาย','Initial thresholds use separate national medians of confirmed positive rates, with at least 5 locations. Otherwise, 1 branch per unit is an exploratory starting point, not sales calibration.')}</p></details><p class="footline">${tr('ฐานตลาดต้องมีข้อมูลและมากกว่าศูนย์ มิฉะนั้นรอตรวจ · จำนวนสาขาศูนย์บนฐานที่ใช้ได้ มีอัตราศูนย์','The denominator must be known and positive; otherwise review is required. Zero branches over a valid denominator gives a measured zero rate.')}</p>`:`<div class="inline-fields"><div class="field"><label for="own-many">${escapeHTML(ownBrandName())+' '+tr('จุดเทียบช่องว่าง (สาขา)','Gap reference (branches)')}</label><input id="own-many" data-criterion="ownMany" type="number" min="1" max="100" value="${draft.ownMany}"></div><div class="field"><label for="competitor-many">${tr('จุดเทียบช่องว่างคู่แข่ง (สาขา)','Competitor gap reference (branches)')}</label><input id="competitor-many" data-criterion="competitorMany" type="number" min="1" max="100" value="${draft.competitorMany}"></div></div>`}<p class="footline">${tr('ที่จุดเทียบ คะแนนช่องว่างเท่ากับ 50 จาก 100; สาขาน้อยกว่าจุดเทียบได้คะแนนช่องว่างสูงกว่า ค่านี้มีผลเมื่อใช้การจัดอันดับแบบน้ำหนัก','The gap reference gives a gap score of 50/100. Lower supply gives a higher gap score. This affects weighted ranking only.')}</p><a class="btn" href="#supply">${uiIcon('fact_check')}${tr('ดูสาขาและรายการรอตรวจ','Review branches and unverified records')}</a></section>`;
}
function refreshSupplyControls(){const el=document.querySelector('.supply-section');if(el)el.outerHTML=supplyControls();refreshDecisionSection('preferred-types');YolkCriteriaControls.mount();updateImpact()}

function impact(){
 const errors=criteriaErrors(draft);
 if(errors.length)return `<h2>${tr('ตรวจเกณฑ์ก่อนดูผล','Check criteria to preview')}</h2><p>${tr('เปิดสัญญาณ Demand อย่างน้อยหนึ่งกลุ่มและตรวจค่าตัวเลข น้ำหนักที่ใช้งานต้องไม่เป็นศูนย์ทั้งหมด','Enable a Demand group and check the numbers. Each active weight set needs a positive total.')}</p><p class="footline">${tr('Percentile 1–100 · Tier 1 ≥ Tier 2 ≥ Tier 3 ข้อ · น้ำหนัก 0–100','Percentiles 1–100 · Tier hit counts descend from Tier 1 to Tier 3 · weights 0–100')}</p>`;
 const old=evaluate(Y.criteria).filter(a=>a.eligible),next=evaluate(draft).filter(a=>a.eligible),oldIDs=new Set(old.map(a=>a.id)),nextIDs=new Set(next.map(a=>a.id)),oldRanks=new Map(old.map((a,i)=>[a.id,i+1]));
 const added=next.filter(a=>!oldIDs.has(a.id)).length,removed=old.filter(a=>!nextIDs.has(a.id)).length,moved=next.filter((a,i)=>oldRanks.has(a.id)&&oldRanks.get(a.id)!==i+1).length,diff=diffCriteria(Y.criteria,draft);
 return `<h2>${tr('ปรับแล้ว อะไรเปลี่ยน','What changes?')}</h2><p class="lead">${tr('เทียบกับเกณฑ์ทีม','Compared with team criteria')} v${Y.criteria.version}</p><div class="impact-total"><span>${old.length}</span><span>→</span><strong>${next.length}</strong><small>${tr('ทำเลผ่าน Demand ในระดับที่เลือก','locations in the selected Demand levels')}</small></div><div class="impact-delta"><span>+${added} ${tr('เข้าเกณฑ์','newly qualify')}</span><span>−${removed} ${tr('หลุดเกณฑ์','no longer qualify')}</span></div><p class="impact-rank-note"><strong>${moved}</strong> ${tr('ทำเลเดิมมีอันดับเปลี่ยน','previously eligible locations change rank')}<br>${tr('Supply และน้ำหนักเปลี่ยนอันดับได้ แต่ไม่เปลี่ยนจำนวนไข่แดง','Supply and weights can change the order, while the Demand set stays unchanged.')}</p>${next.slice(0,5).map((a,i)=>`<div class="mini-row"><span class="mini-rank">${i+1}</span><span>${escapeHTML(areaName(a.id))}<small>${escapeHTML(provinceName(a.province))} · ${YolkDecisions.tierText(a)}</small><span class="rank-move">${oldRanks.has(a.id)?tr('อันดับ ','Rank ')+oldRanks.get(a.id)+' → '+(i+1):tr('เข้าใหม่','Newly eligible')}</span></span><span class="num">${YolkDecisions.rankText(a,draft)}</span></div>`).join('')}<p class="footline">${YolkDecisions.rankLabel(draft)} · ${tr('เป็นแบบร่างจนกดใช้กับทีม','Draft until applied to the workspace')}</p><button class="btn primary apply-button" data-action="apply-criteria" ${!canEdit()||!diff.length?'disabled':''}>${uiIcon('save')}${tr('ใช้เกณฑ์นี้กับทีม','Apply to workspace')}</button><p class="scope-note">${tr('บันทึกค่าเดิม–ใหม่ในประวัติ และแจ้งสมาชิกอีก 9 คน','Saves before/after values to the feed and notifies the other 9 members.')}</p>${!canEdit()?`<p class="tag wait">${tr('Viewer ทดลองปรับได้ แต่ใช้กับทีมไม่ได้','Viewers can preview, but cannot apply team changes.')}</p>`:''}`;
}

function geographySummary(){return `<section class="geography-summary"><div><span class="eyebrow">${tr('หน่วยวิเคราะห์คงที่','Pinned analytical universe')}</span><strong>${tr('7,954 หน่วย: กทม. 180 แขวง · ต่างจังหวัด 7,774 อปท.','7,954 units: 180 Bangkok khwaeng · 7,774 upcountry LAOs')}</strong><p>${tr('ทุกธุรกิจใช้ Percentile ฐานทั้งประเทศเดียวกัน เฉพาะค่าที่ต้นทางมี; การกรองจังหวัดไม่เปลี่ยนฐาน ขอบเขตเป็น reporting unit ไม่ใช่การยืนยันขอบเขตกฎหมาย','All three businesses use the fixed national universe, known values per metric. Province filters do not rebaseline. Source reporting units are not independent statutory-boundary verification.')}</p></div></section>`}

function mobileImpact(){let valid=criteriaErrors(draft).length===0,old=evaluate(Y.criteria).filter(a=>a.eligible).length,next=valid?evaluate(draft).filter(a=>a.eligible).length:'—';return `<div id="mobile-impact" class="mobile-impact"><div aria-live="polite"><span>${tr('ทำเลผ่านเกณฑ์ · ทดลอง','Eligible locations · draft')}</span><strong>${old} → ${next}</strong></div><button class="btn primary" data-action="jump-preview">${uiIcon('tune')}${tr('ดูผลเปลี่ยนแปลง','Review impact')}</button></div>`}
function criteria(){return `<div class="criteria-workspace-head"><div><h1>${tr('หาไข่แดง แล้วดูช่องว่าง','Find Yolks, then compare supply')}</h1><p>${tr('สองคำถามบนแผนที่เดียว ทดลองก่อนใช้กับทีม','Two questions on one map. Preview before applying to the team.')}</p></div><span class="version-tag">${tr('เกณฑ์ทีม','Team criteria')} v${Y.criteria.version}</span></div><div class="criteria-live-workspace"><section class="criteria-control-panel" aria-label="${tr('ตัวปรับเกณฑ์','Criteria controls')}"><div class="criteria-tabs" role="tablist" aria-label="${tr('ขั้นตอนเลือกทำเล','Location decision steps')}">${[['demand','1. หาไข่แดง','1. Find Yolks','egg_alt'],['supply','2. ดูช่องว่าง','2. Compare supply','shield']].map(([id,th,en,icon])=>`<button type="button" role="tab" id="tab-${id}" aria-controls="pane-${id}" data-criteria-tab="${id}" aria-selected="${id==='demand'}">${uiIcon(icon)}${tr(th,en)}</button>`).join('')}</div><div class="criteria-control-scroll">${[['demand',demandControls()],['supply',`<section class="section compare-intro"><h2>${uiIcon('shield')}${tr('2. ดูช่องว่างสาขา','2. Compare branch supply')}</h2><p>${tr('โล่ = สาขาเรา · ดาบ = คู่แข่ง เปรียบเทียบก่อนเลือกทำเลไปสำรวจ','Shield = our stores · swords = competitors. Compare before choosing places to explore.')}</p><p>${tr('Demand คัดทำเลแล้ว ขั้นนี้ปรับลำดับ ไม่เปลี่ยนจำนวนไข่แดง','Demand already selects the set. This step changes its order, not the Yolk count.')}</p></section>`+YolkDecisions.ranking()+`<details class="simple-advanced supply-advanced"><summary>${uiIcon('tune')}${tr('ปรับวิธีเทียบ Supply และจุดเทียบช่องว่าง','Advanced Supply method and gap references')}</summary>${supplyControls()}</details>`]].map(([id,html])=>`<div role="tabpanel" id="pane-${id}" aria-labelledby="tab-${id}" data-criteria-pane="${id}" ${id!=='demand'?'hidden':''}>${html}</div>`).join('')}</div><div class="criteria-control-footer"><button class="btn primary criteria-expanded-apply" data-action="apply-criteria" ${!canEdit()||criteriaErrors(draft).length||!diffCriteria(Y.criteria,draft).length?'disabled':''}>${uiIcon('save')}${tr('ใช้กับทีม','Apply to team')}</button><span>${tr('แบบร่างส่วนตัว','Private draft')}</span><button class="btn" data-action="reset-draft">${uiIcon('history')}${tr('คืนค่า','Reset')}</button></div></section></div><div class="criteria-shortlist-step"><strong>${uiIcon('bookmark_add')}${tr('3. เล็งทำเลที่อยากไปต่อ','3. Shortlist places to explore')}</strong><p>${tr('เปิดทำเลบนแผนที่ เทียบสาขาและหลักฐาน แล้วกด “เล็งทำเลนี้”','Open a place on the map, compare supply and evidence, then add it to the shortlist.')}</p><a class="btn" href="#demand">${uiIcon('location_on')}${tr('ดูไข่แดงและเล็งทำเล','Explore and shortlist Yolks')}</a></div><details class="criteria-impact-details"><summary>${uiIcon('fact_check')}${tr('ผลเปลี่ยนแปลงและประวัติเกณฑ์','Impact and criteria history')}</summary><section class="section preview-box" id="impact-preview" tabindex="-1">${impact()}</section>${geographySummary()}<section class="section full-feed"><h2>${tr('ใครปรับอะไร เมื่อไร','Who changed what, and when')}</h2>${feed(currentCriteriaEvents(),{links:false})}</section></details>`}




function place(){let a=evaluate().find(x=>x.id===Y.selected);if(!a)return `<div class="empty">${tr('ไม่พบทำเล','Location not found')}</div>`;let t=Y.targets[a.id]?.archived?null:Y.targets[a.id],events=Y.events.filter(e=>(e.entity==='place'&&e.entity_id===a.id)||(e.entity==='supply'&&(e.meta.area===a.id||e.meta.previousArea===a.id)));return `<a class="back" href="#market">${uiIcon('arrow_back')}${tr('กลับไปภาพรวมประเทศ','Back to market map')}</a><div class="page-head"><div><p class="eyebrow">${escapeHTML(provinceName(a.province))} · ${tr(a.geoType==='khwaeng'?'แขวง':'อปท.',a.geoType==='khwaeng'?'Khwaeng':'Local authority')}</p><h1>${escapeHTML(areaName(a.id))}</h1><p>${tr('บริบทพื้นที่และช่องว่างเครือข่ายที่เลือก','Area context and gaps in the selected network.')}</p></div><button class="btn" data-action="share">${uiIcon('share')}${tr('แชร์ทำเล','Share location')}</button></div><div class="location-verdict">${yolkBadge(a)}<span class="tag ${a.eligible?'high':'wait'}">${a.eligible?tr('ผ่านเกณฑ์ทีม','Meets team criteria'):tr('ยังไม่เข้าเกณฑ์ทีม','Outside team shortlist criteria')}</span><strong>${YolkDecisions.tierText(a)}</strong><a href="#criteria">${tr('เกณฑ์ทีม','Team criteria')} v${Y.criteria.version}</a></div>${YolkDecisions.detail(a)}${YolkLocationReview.detail(a)}${renderMarketLandscape(a)}<div class="location-sources"><span class="tag">${tr('บริบทพื้นที่จาก CityMETER','CityMETER area context')}</span><button class="quiet-link" data-action="place-branches">${uiIcon(Y.industry==='fuel'?'local_gas_station':'store')}${tr('ดูสาขาในทำเลนี้','View available branch records')} →</button></div><div class="detail-grid"><div><section class="section"><h2>${tr('งานของทำเลนี้','Location work')}</h2>${t?`<form id="target-form"><div class="inline-fields"><div class="field"><label for="target-owner">${tr('ผู้รับผิดชอบ','Owner')}</label><select id="target-owner" name="owner" ${!canEdit()?'disabled':''}>${PEOPLE.filter(p=>p.role!=='viewer').map(p=>`<option value="${p.id}" ${t.owner===p.id?'selected':''}>${person(p.id)}</option>`).join('')}</select></div><div class="field"><label for="target-status">${tr('สถานะ','Status')}</label><select id="target-status" name="status" ${!canEdit()?'disabled':''}>${['survey','study','hold','rejected'].map(v=>`<option value="${v}" ${t.status===v?'selected':''}>${tr(...valLabels[v])}</option>`).join('')}</select></div></div><div class="field"><label for="target-note">${tr('บันทึกของทีม','Team note')}</label><textarea id="target-note" name="note" rows="3" maxlength="1000" ${!canEdit()?'disabled':''}>${escapeHTML(t.note)}</textarea></div><div class="form-actions"><button class="btn primary" type="submit" ${!canEdit()?'disabled':''}>${uiIcon('save')}${tr('บันทึกและแจ้งทีม','Save & notify team')}</button><button class="quiet-link" type="button" data-action="target" data-id="${a.id}" ${!canEdit()?'disabled':''}>${uiIcon('delete')}${tr('นำออกจากรายการเล็งไว้','Remove from shortlist')}</button></div></form>`:`<p>${tr('เล็งทำเลนี้ไว้ แล้วมอบหมายงานและบันทึกสิ่งที่พบ','Shortlist this location to assign work and record field findings.')}</p><button class="btn primary" data-action="target" data-id="${a.id}" ${!canEdit()?'disabled':''}>${uiIcon('bookmark_add')}${tr('เล็งทำเลนี้','Shortlist location')}</button>`}</section></div><aside><section class="section full-feed"><div class="block-title"><h2>${tr('ประวัติทำเล','Location feed')}</h2><span class="tag">${events.length}</span></div>${feed(events,{limit:12,links:false})}</section><p class="data-disclosure">${tr('บริบท CityMETER ตาม UUID · พิกัดรายสาขาแยกหลักฐานจากยอดรวม · บันทึกและแจ้งเตือนในเครื่อง','CityMETER reporting-UUID context · POI coordinates are separate evidence from aggregate counts · Local edits and notifications.')}</p></aside></div>`}

function targets(){let list=evaluate().filter(a=>Y.targets[a.id]&&!Y.targets[a.id].archived&&inMapArea(a));return `<div class="page-head"><div><h1>${tr('จากทำเลที่น่าสนใจ สู่แผนของทีม','From promising places to a team plan.')}</h1><p>${tr('ผู้รับผิดชอบ สถานะ และบันทึก ใช้ร่วมกันทั้งทีม','Owners, status and notes are shared across the workspace.')}</p></div><a class="btn primary" href="#market">${tr('ค้นหาทำเลเพิ่ม','Explore more locations')}</a></div><div class="shortlist-grid">${list.map((a,i)=>`<div>${placeRow(a,i)}<div class="target-meta"><span>${person(Y.targets[a.id].owner)}</span><span>${tr(...valLabels[Y.targets[a.id].status])}</span></div></div>`).join('')||`<div class="empty">${tr('ยังไม่มีทำเลที่เล็งไว้ ลองเริ่มจากภาพรวมประเทศ','No shortlisted locations yet. Start with the market map.')}</div>`}</div><section class="section full-feed"><h2>${tr('ความเคลื่อนไหวของทำเล','Location activity')}</h2>${feed(Y.events.filter(e=>e.entity==='place'))}</section>`}
function activityPage(inbox=false){let events=inbox?Y.events.filter(e=>e.recipients.includes(Y.actor)):Y.events;return `<div class="page-head"><div><h1>${inbox?tr('มีอะไรเปลี่ยนไปบ้าง','What’s changed?'):tr('ทีมกำลังขยับไปทางไหน','Keep up with the team.')}</h1><p>${inbox?tr('การเปลี่ยนแปลงที่เพื่อนร่วมทีมแจ้งถึงคุณ','Changes your teammates shared with you.'):tr('ดูว่าใครเปลี่ยนอะไร เมื่อไร และค่าก่อน–หลัง','Every saved change has an actor, time and before/after values.')}</p></div>${inbox?`<button class="btn" data-action="read-all">${tr('อ่านทั้งหมดแล้ว','Mark all as read')}</button>`:''}</div>${inbox?`<div class="inbox-summary"><strong>${unreadCount()}</strong><span>${tr('ยังไม่ได้อ่าน','unread')} · ${person(Y.actor)}</span><small>${tr('สลับผู้ใช้ตัวอย่างด้านบนเพื่อดูการแจ้งเตือนของเพื่อนร่วมทีม','Switch demo users above to view a teammate’s inbox')}</small></div>`:`<div class="team-strip"><strong>${escapeHTML(YolkBrands.displayName(Y.ownBrandId,ownBrandName()))+' · '+tr('ทีมขยายสาขา','Expansion team')}</strong><span>1 Admin · 3 Editors · 6 Viewers</span><span>${tr('ทุกคนเห็นข้อมูลชุดเดียวกัน','One shared workspace')}</span></div>`}${inbox?'':renderLeaderboard()}<section class="section full-feed feed-wide">${feed(events,{limit:50})}</section><p class="footline">${tr('ต้นแบบบันทึกในเครื่อง · Email / LINE เป็นตัวอย่าง ยังไม่ส่งจริง','Notifications are local in this prototype · Email / LINE show share previews; nothing is sent.')}</p>`}
function showShare(){let a=AREAS.find(a=>a.id===Y.selected);$('#share-dialog').innerHTML=`<h2>${tr('แชร์บริบทให้ทีม','Share the context')}</h2><p>${tr('ผู้รับที่มีสิทธิ์เปิดทำเลและเกณฑ์เวอร์ชันนี้ได้','Authorized recipients can open this location with this criteria version.')}</p><div class="share-preview"><strong>CityMETER: Yolk</strong><p>${escapeHTML(provinceName(a.province))} · ${escapeHTML(areaName(a.id))}</p><span>${tr('เกณฑ์ทีม','Team criteria')} v${Y.criteria.version}</span></div><div class="share-actions"><button class="btn" data-action="preview-email">Email</button><button class="btn" data-action="preview-line">LINE</button><button class="btn primary" data-action="close-share">${uiIcon('close')}${tr('ปิด','Close')}</button></div><p class="footline">${tr('ตัวอย่างข้อความแชร์เท่านั้น ยังไม่ส่งออกนอกต้นแบบ','Message preview only. No external delivery in this prototype.')}</p><p id="channel-preview" role="status"></p>`;$('#share-dialog').showModal()}

function teamPage(){return `<div class="page-head"><div><h1>${tr('สิบคน ทำงานบนข้อมูลเดียวกัน','Ten people. One shared workspace.')}</h1><p>${tr('Admin 1 คน · Editors 3 คน · Viewers 6 คน','1 Admin · 3 Editors · 6 Viewers')}</p></div><span class="tag">Enterprise · 10 / 10</span></div><div class="detail-grid"><section class="section"><h2>${tr('สมาชิกตัวอย่าง','Demo members')}</h2>${PEOPLE.map(p=>`<div class="team-seat"><span>${person(p.id)} ${p.id===Y.actor?'· '+tr('คุณ','You'):''}</span><span>${p.role}</span></div>`).join('')}</section><aside><section class="section"><h2>${tr('ใครทำอะไรได้','Who can do what')}</h2><p><strong>Admin</strong><br>${tr('กำหนดสิทธิ์และนโยบายข้อมูล พร้อมแก้ไขงานของทีม','Manages members and data policy, and edits shared work.')}</p><p><strong>Editors</strong><br>${tr('บันทึกสาขา ทำเล และใช้เกณฑ์กับ workspace','Edit branches and locations, and apply shared criteria.')}</p><p><strong>Viewers</strong><br>${tr('อ่าน ทดลองเกณฑ์ และติดตามความเคลื่อนไหว','Read, preview criteria, and follow team activity.')}</p><p class="data-disclosure">${tr('สลับผู้ใช้ด้านบนเพื่อทดลองสิทธิ์ ยังไม่มีบัญชีหรือคำเชิญจริง','Switch the demo user above to try roles. This prototype has no real authentication or invitations.')}</p></section></aside></div>`}

let renderedRoute='',renderedFocus='',renderedHash='',renderedContext='';
function workingForm(){const f=$('#poi-form')||$('#target-form');if(!f||renderedHash!==location.hash||renderedContext!==criteriaContextKey())return null;const values=Object.fromEntries(new FormData(f)),active=document.activeElement;return {id:f.id,recordId:f.dataset.id,recordRevision:f.dataset.revision,values,focus:active?.id,selection:typeof active?.selectionStart==='number'?[active.selectionStart,active.selectionEnd]:null,province:$('#branch-province')?.value,branchContext:window.YolkBranchContext?.snapshot(f)}}
function restoreWorkingForm(v){if(!v)return;const f=$('#'+v.id);if(!f||v.recordId!==f.dataset.id)return;if(v.recordRevision!==undefined)f.dataset.revision=v.recordRevision;if(v.id==='poi-form'&&v.province){$('#branch-province').value=v.province;$('#branch-area').innerHTML=areaOptions(v.province,v.values.area)}for(const [name,value]of Object.entries(v.values))if(f.elements[name]&&f.elements[name].type!=='file')f.elements[name].value=value;if(v.id==='poi-form')window.YolkBranchContext?.restore(f,v.branchContext);const active=v.focus&&$('#'+v.focus);if(active){active.focus({preventScroll:true});if(v.selection&&active.setSelectionRange)active.setSelectionRange(...v.selection)}}
function render(preserve=true){const preservedForm=preserve===false?null:workingForm();clearTimeout(impactTimer);impactTimer=0;let route=(location.hash.slice(1).split('/')[0]||'market');if(!['market','demand','targets','supply','criteria','feed','place','poi','inbox','team'].includes(route))route='market';if(route==='place'){let id=location.hash.split('/')[1];if(AREAS.some(a=>a.id===id))Y.selected=id}Y.route=route;header();$('.skip').textContent=tr('ข้ามไปเนื้อหา','Skip to content');$('#mobile-nav').setAttribute('aria-label',tr('เมนูหลัก','Primary navigation'));$('#content').innerHTML=contextControls()+(Y.loading?`<section class="section"><p role="status">${tr('กำลังอ่าน Snapshot ของธุรกิจที่เลือก…','Loading the selected industry snapshot…')}</p></section>`:Y.loadError?`<section class="section"><p role="alert">${escapeHTML(Y.loadError)}</p></section>`:({market,demand:()=>YolkAnalysisUI.demandPage(),targets,supply,criteria,feed:()=>activityPage(),inbox:()=>activityPage(true),place,poi:poiEditor,team:teamPage}[route])()+sourceSummary());if(renderedHash!==location.hash||renderedContext!==criteriaContextKey())$('#content').scrollTop=0;if(route==='supply'){let heads=[...document.querySelectorAll('.supply-table th')].map(el=>el.textContent);document.querySelectorAll('.supply-table tbody tr').forEach(row=>[...row.children].forEach((cell,i)=>cell.setAttribute('data-label',heads[i])))}if(!Y.loading&&(route==='place'||route==='supply'))ensureSourcePoints();if(route==='place'&&!Y.loading)ensureSourceGeometry();if(route==='poi')YolkBranchPhotos.bind(document,{lang:Y.lang,editable:canEdit(),canEdit});if(route==='criteria'){YolkDecisions.sync();YolkCriteriaControls.mount();YolkCriteriaMap.mountControls();YolkSimpleCriteria.sync()}YolkWorkspaceMap.mount({onNavigate(path){Y.province=path.provinceCode||'';Y.poiArea=path.level==='location'?path.areaId:'';Y.marketPage=0;Y.page=0;render()},onProvince(code){Y.province=code;Y.marketPage=0;render()},onAnalysisReady(){render()},onArea(id){Y.selected=id;location.hash='place/'+id},onPoi(id){location.hash='poi/'+id}});const focusKey=(route==='place'||route==='poi')?location.hash:'';if(focusKey&&focusKey!==renderedFocus){if(route==='place')YolkWorkspaceMap.focusArea(Y.selected);else if(location.hash.split('/')[1]!=='new')YolkWorkspaceMap.focusPoi(location.hash.split('/')[1])}renderedFocus=focusKey;renderedRoute=route;renderedHash=location.hash;renderedContext=criteriaContextKey();restoreWorkingForm(preservedForm);if(route==='poi')window.YolkBranchContext?.bind();if(preservedForm&&route==='poi')YolkWorkspaceMap.sync();YolkIcons.captionControls(document)}
let impactTimer=0;
function queueImpact(){stashContext();YolkCriteriaControls.sync();YolkWorkspaceMap.pending();document.querySelectorAll('[data-action=apply-criteria]').forEach(b=>b.disabled=true);if(impactTimer)return;const contextKey=criteriaContextKey();impactTimer=setTimeout(()=>{impactTimer=0;if(Y.route==='criteria'&&criteriaContextKey()===contextKey)updateImpact()},120)}
function updateImpact(){clearTimeout(impactTimer);impactTimer=0;stashContext();if(!$('#impact-preview'))return;$('#impact-preview').innerHTML=impact();YolkDecisions.sync();YolkCriteriaControls.mount();YolkWorkspaceMap.sync();YolkSimpleCriteria.sync();document.querySelectorAll('[data-action=apply-criteria]').forEach(b=>b.disabled=!canEdit()||criteriaErrors(draft).length>0||!diffCriteria(Y.criteria,draft).length);document.querySelectorAll('[data-cutoff-id]').forEach(el=>{let id=el.dataset.cutoffId,p=BUILDING_IDS.includes(id)?draft.buildingP2:draft.activityP;el.textContent='P'+p+' ≥ '+num(cutoff(id,p),2)});YolkIcons.captionControls(document)}

function refreshDecisionSection(id){let el=$('#'+id);if(el)el.outerHTML=id==='preferred-types'?YolkDecisions.preferred():YolkDecisions.ranking();YolkDecisions.sync();YolkCriteriaControls.mount()}


const committed=()=>{stashContext();refreshPointRelations();notify(tr('บันทึกแล้ว · แจ้งสมาชิกอื่น 9 คนในต้นแบบ','Saved · notified the other 9 demo members'))};
document.addEventListener('input',e=>{let el=e.target;if(['location-search','poi-search'].includes(el.id)){let id=el.id,value=el.value,contextAtSearch=criteriaContextKey(),routeAtSearch=location.hash;clearTimeout(window.searchTimer);window.searchTimer=setTimeout(()=>{if(contextAtSearch!==criteriaContextKey()||routeAtSearch!==location.hash||!$('#'+id))return;let focused=document.activeElement?.id===id,pos=el.selectionStart;if(id==='location-search'){Y.listQuery=value;Y.marketPage=0}else{Y.poiQuery=value;Y.page=0}render();if(focused){let input=$('#'+id);input.focus();input.setSelectionRange(pos,pos)}},250)}if(el.dataset.criterion){draft[el.dataset.criterion]=el.value===''?NaN:+el.value;queueImpact();if(['ownMany','competitorMany','ownRateHigh','competitorRateHigh'].includes(el.dataset.criterion))refreshDecisionSection('preferred-types')}if(el.dataset.weightScope){draft[el.dataset.weightScope][el.dataset.weightKey]=el.value===''?NaN:+el.value;YolkCriteriaMap.showRanking();queueImpact()}});
document.addEventListener('change',e=>{let el=e.target;if(el.name==='map-scope'){Y.mapScope=el.value==='all'?'all':'preferred';render();document.querySelector('input[name="map-scope"]:checked')?.focus();return}if(el.id==='actor-select'){Y.actor=el.value;save();render();$('#actor-select').focus()}if(el.dataset.pattern){draft.patterns=patternNames.filter(n=>n===el.dataset.pattern?el.checked:draft.patterns.includes(n));el.closest('.preferred-card')?.classList.toggle('is-selected',el.checked);updateImpact()}if(el.dataset.toggle){draft[el.dataset.toggle]=el.checked;refreshDecisionSection('ranking-weights');updateImpact()}if(el.dataset.extra){draft.extraMetrics=METRICS.filter(m=>m.ready&&!enabledMetricIds({...draft,extraMetrics:[]}).includes(m.id)&&(m.id===el.dataset.extra?el.checked:draft.extraMetrics.includes(m.id))).map(m=>m.id);refreshDecisionSection('ranking-weights');updateImpact()}if(el.id==='demand-mode'){draft.demandMode=el.value;refreshDecisionSection('preferred-types');$('#demand-mode').focus();updateImpact()}if(el.id==='max-demand-tier'){draft.maxDemandTier=+el.value;updateImpact()}if(el.id==='ranking-mode'){draft.rankingMode=el.value;refreshDecisionSection('ranking-weights');$('#ranking-mode').focus();updateImpact()}if(el.id==='brand-filter'){Y.brandFilter=el.value;Y.page=0;render()}if(el.id==='leader-period'||el.id==='leader-category'){Y[el.id==='leader-period'?'leaderPeriod':'leaderCategory']=el.value;render();$('#'+el.id).focus()}});
document.addEventListener('keydown',e=>{if(e.target.matches('svg [data-action="province"]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
document.addEventListener('click',async e=>{let b=e.target.closest('[data-action]');if(!b||b.disabled)return;let action=b.dataset.action,id=b.dataset.id;switch(action){case 'language':Y.lang=Y.lang==='th'?'en':'th';save();render();$('.language-toggle').focus();break;case 'inbox':location.hash='inbox';break;case 'market-prev':Y.marketPage=Math.max(0,Y.marketPage-1);render();break;case 'market-next':Y.marketPage++;render();break;case 'province':Y.marketPage=0;Y.province=b.dataset.code;Y.listQuery='';render();$('#province-results').focus({preventScroll:true});if(window.innerWidth<1100)$('#province-results').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});break;case 'clear-province':Y.province='';Y.marketPage=0;YolkWorkspaceMap.home();render();break;case 'place':Y.selected=id;location.hash='place/'+id;break;case 'target':{if(!canEdit())return;let had=!!Y.targets[id]&&!Y.targets[id].archived;if(Y.targets[id])Y.targets[id].archived=had;else Y.targets[id]={owner:Y.actor,status:'study',note:'',archived:false};emitEvent(had?'place.removed':'place.created','place',id,[{field:'target',before:had,after:!had}]);render();committed();break}case 'reset-draft':draft=structuredClone(Y.criteria);draftBase=Y.criteria.version;stashContext();render();break;case 'apply-criteria':{if(!canEdit())return;if(draftBase!==Y.criteria.version){notify(tr('เกณฑ์ทีมเปลี่ยนแล้ว กดคืนค่าเกณฑ์ทีมก่อนลองอีกครั้ง','Team criteria changed. Reset to team settings before trying again.'));return}if(criteriaErrors(draft).length){notify(tr('ตรวจเกณฑ์ตัวเลขและเปิดสัญญาณ Demand อย่างน้อยหนึ่งกลุ่ม','Check numeric thresholds and enable at least one demand signal group.'));return}let changes=diffCriteria(Y.criteria,draft);if(!changes.length)return;const previous=Y.criteria,previousBase=draftBase,unsaved=structuredClone(draft);Y.criteria={...structuredClone(draft),version:Y.criteria.version+1};const event=emitEvent('criteria.updated','criteria',criteriaContextKey(),changes,{version:Y.criteria.version});if(!event){Y.criteria=previous;draft=unsaved;draftBase=previousBase;updateImpact();return}draft=structuredClone(Y.criteria);draftBase=Y.criteria.version;stashContext();render();committed();break}case 'supply-tab':Y.poiTab=b.dataset.tab;if(['own','competitor','all'].includes(Y.poiTab))YolkAnalysisUI.set('relation',Y.poiTab==='all'?'total':Y.poiTab);Y.page=0;render();break;case 'poi-prev':Y.page=Math.max(0,Y.page-1);render();break;case 'poi-next':Y.page++;render();break;case 'new-poi':if(canEdit())location.hash='poi/new';break;case 'edit-poi':location.hash='poi/'+id;break;case 'archive-poi':case 'restore-poi':{if(!canEdit())return;let p=Y.pois.find(p=>p.id===id),before=p.archived;p.localOverlay=true;p.industryId=Y.industry;p.archived=action==='archive-poi';p.revision++;emitEvent(p.archived?'supply.archived':'supply.restored','supply',id,[{field:'archived',before,after:p.archived}],{area:p.area});render();committed();break}case 'place-branches':{let a=AREAS.find(x=>x.id===Y.selected);Y.poiQuery='';Y.poiArea=a.id;Y.poiTab='all';Y.brandFilter='';Y.page=0;location.hash='supply';break}case 'clear-area':Y.poiArea='';Y.poiQuery='';render();break;case 'show-all-branches':Y.province='';Y.poiArea='';Y.poiQuery='';YolkWorkspaceMap.home();render();break;case 'event-context':{const requestedHash=location.hash;let x=Y.events.find(x=>x.id===id),route=await eventContextRoute(x);if(!route||location.hash!==requestedHash)return;Y.read[Y.actor]=[...new Set([...(Y.read[Y.actor]||[]),id])];save();if(location.hash==='#'+route)render();else location.hash=route;break}case 'jump-preview':$('#impact-preview').focus({preventScroll:true});$('#impact-preview').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});break;case 'read-all':Y.read[Y.actor]=Y.events.filter(x=>x.recipients.includes(Y.actor)).map(x=>x.id);save();render();break;case 'share':showShare();break;case 'close-share':$('#share-dialog').close();break;case 'preview-email':case 'preview-line':$('#channel-preview').textContent=tr('ตัวอย่างสำหรับ ','Preview for ')+(action==='preview-line'?'LINE':'Email')+': '+tr('ชวนดูทำเลนี้ด้วยเกณฑ์ทีม v','Review this location with team criteria v')+Y.criteria.version;break}});
document.addEventListener('submit',async e=>{if(!['poi-form','target-form'].includes(e.target.id))return;e.preventDefault();if(!canEdit())return;let form=e.target,data=Object.fromEntries(new FormData(form));if(form.id==='target-form'){let t=Y.targets[Y.selected],changes=['owner','status','note'].filter(k=>t[k]!==data[k]).map(k=>({field:k,before:t[k],after:data[k]}));if(!changes.length)return;t={...t,...data};Y.targets[Y.selected]=t;emitEvent('place.updated','place',Y.selected,changes);render(false);committed();return}let p=Y.pois.find(p=>p.id===form.dataset.id),fresh=!p;let error=msg=>{const output=form.isConnected?form.querySelector('#form-error'):null;if(output)output.textContent=msg;else notify(msg)};for(let k of Object.keys(data))if(typeof data[k]==='string')data[k]=data[k].trim();if(fresh&&!data.name)return error(tr('ระบุชื่อสาขา','Enter the branch name.'));if(data.area&&!AREA_INDEX.has(data.area))return error(tr('เลือกทำเลจากรายการที่มี','Choose an available location.'));if(fresh&&!data.area&&!window.YolkBranchContext.coordinatePair(data.lat,data.lng))return error(tr('ระบุพิกัดทั้งคู่หรือเลือกทำเล เพื่อวางสาขาบนแผนที่','Enter coordinates or choose a location to place this branch.'));if(data.relation!=='unverified'&&!data.brand)return error(tr('ระบุแบรนด์ของสาขานี้','Enter the branch brand.'));if(data.relation==='unverified'&&data.status==='active')return error(tr('สาขาที่ยังไม่ทราบประเภทต้องเป็นรอตรวจสอบก่อน','An unverified relationship must remain pending.'));if(!!data.lat!==!!data.lng||data.lat&&(!Number.isFinite(+data.lat)||!Number.isFinite(+data.lng)||Math.abs(+data.lat)>90||Math.abs(+data.lng)>180))return error(tr('กรอกพิกัดทั้งคู่ให้ถูกต้อง','Enter a valid latitude and longitude pair.'));let verifying=data.status==='active'&&data.relation!=='unverified'&&(fresh||p.status!=='active'||p.relation==='unverified');if(verifying&&!data.note)return error(tr('เพิ่มหลักฐานหรือบันทึกการตรวจสอบก่อนยืนยัน','Add an evidence note before verifying this branch.'));const identity=window.YolkBranchContext.canonicalBrand(data.brand,p?.brandId);if(identity)data.brand=identity.name;let dup=Y.pois.find(x=>!x.archived&&x.id!==p?.id&&((!!data.area&&x.area===data.area)||(!data.area&&data.lat!==''&&data.lng!==''&&x.lat===+data.lat&&x.lng===+data.lng))&&!!data.name&&String(x.name||'').toLowerCase()===data.name.toLowerCase()&&(identity?.id?x.brandId===identity.id||String(x.brand||'').toLowerCase()===data.brand.toLowerCase():String(x.brand||'').toLowerCase()===data.brand.toLowerCase()));if(dup)return error(tr('มีสาขาชื่อนี้ แบรนด์นี้ ในทำเลเดียวกันแล้ว','This branch name and brand already exist in the location.'));if(data.relation==='own'&&identity?.id!==Y.ownBrandId)return error(tr('สาขาเราต้องใช้ชื่อ identity ที่เลือก: ','Own records must use the selected identity: ')+ownBrandName());if(p&&+form.dataset.revision!==p.revision)return error(tr('รายการนี้ถูกแก้ไขแล้ว เปิดใหม่ก่อนบันทึก','This record changed. Reopen it before saving.'));data.localOverlay=true;data.industryId=Y.industry;data.brandId=identity?.id||null;data.province=AREA_INDEX.get(data.area)?.province||data.province||null;data.area=data.area||null;data.supplyScope=Y.supplyScope;const spatialChange=['area','province','lat','lng'].some(k=>String(p?.[k]??'')!==String(data[k]??''));if(spatialChange)data.assignmentSuggestion=window.YolkBranchContext.assignment(form)||{method:'team_entered',legalBoundaryIndependentlyVerified:false};data.name=data.name||null;data.lat=data.lat===''?null:+data.lat;data.lng=data.lng===''?null:+data.lng;let keys=['name','brand','brandId','relation','status','province','area','lat','lng','note'],changes=keys.filter(k=>p?.[k]!==data[k]).map(k=>({field:k,before:p?.[k]??null,after:data[k]}));
const photoId=form.dataset.photoDraftId||form.dataset.id,photoDraft=YolkBranchPhotos.read(photoId);
if(photoDraft.busy||!photoDraft.ready)return error(tr('รอเตรียมรูปให้เสร็จก่อนบันทึก','Wait for the photos to finish preparing.'));
if(form.dataset.saving==='true')return;
if(!changes.length&&!photoDraft.dirty)return;
const branchId=p?.id||'poi-'+crypto.randomUUID(),actorAtSave=Y.actor,baseRevision=p?.revision,contextAtSave=criteriaContextKey(),requestAtSave=industryRequest,routeAtSave=location.hash;
const beforePhotos=p?.photos||photoDraft.savedPhotos||[];
const previousArea=p?.area,oldPois=structuredClone(Y.pois),oldEvents=structuredClone(Y.events);
let photoCommitted=false,workspaceCommitted=false;form.dataset.saving='true';const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;
try {
  const photoResult=photoDraft.dirty?await YolkBranchPhotos.commit(photoId,branchId):photoDraft;
  photoCommitted=photoDraft.dirty;
  if(contextAtSave!==criteriaContextKey()||requestAtSave!==industryRequest||routeAtSave!==location.hash||Y.loading||Y.loadError)throw Error(tr('บริบทหรือหน้าเปลี่ยนระหว่างบันทึก ร่างรูปยังอยู่ กรุณากลับไปตรวจแล้วบันทึกใหม่','Context or page changed while saving. The photo draft is retained; return to review and save again.'));
  if(!canEdit()||Y.actor!==actorAtSave)throw Error(tr('ผู้ใช้เปลี่ยนแล้ว กรุณาตรวจสิทธิ์และบันทึกใหม่','The active user changed. Check access and save again.'));
  if(p&&p.revision!==baseRevision)throw Error(tr('สาขานี้ถูกแก้ไขระหว่างบันทึก เปิดใหม่เพื่อตรวจข้อมูล','This branch changed while saving. Reopen to review it.'));
  if(photoDraft.dirty){data.photos=photoResult.photos;changes.push({field:'photos',before:beforePhotos.map(({id,title,cover})=>({id,title,cover})),after:photoResult.photos.map(({id,title,cover})=>({id,title,cover}))})}
  if(fresh){p={id:branchId,...data,revision:1,archived:false,sourceDataset:'workspace',operatingStatus:'not_independently_verified'};Y.pois.push(p)}else{Object.assign(p,data);p.revision++}
  const event=emitEvent(fresh?'supply.created':verifying?'supply.verified':'supply.updated','supply',p.id,changes,{area:p.area,previousArea});
  if(!event){Y.pois=oldPois;Y.events=oldEvents;throw Error(tr('บันทึกข้อมูลสาขาไม่สำเร็จ กรุณาลองอีกครั้ง','Could not save the branch. Please try again.'))}
  workspaceCommitted=true;YolkBranchPhotos.finalizeCommit(branchId);location.hash='poi/'+p.id;render(false);committed();
} catch(err){if(photoCommitted&&!workspaceCommitted){try{await YolkBranchPhotos.rollbackCommit(branchId)}catch(rollbackError){err.message+=' · '+rollbackError.message}}error(err.message||tr('บันทึกไม่สำเร็จ กรุณาลองอีกครั้ง','Save failed. Please try again.'))}
finally{form.dataset.saving='false';if(submit)submit.disabled=!canEdit()}
});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#content').focus({preventScroll:true})});render();

document.addEventListener('change',async event=>{const el=event.target;if(el.id==='industry-select')return selectIndustryContext(el.value);if(el.id==='own-brand-select')return selectIndustryContext(Y.industry,el.value);if(el.id==='supply-scope-select')return selectIndustryContext(Y.industry,Y.ownBrandId,el.value);
 if(el.matches('[data-picker-metric],[data-picker-dataset]')){let value=el.value;if(el.hasAttribute('data-picker-dataset'))value=METRICS.find(m=>m.ready&&m.dataset===value).id;if(el.dataset.pathIndex!==undefined)draft.paths[+el.dataset.pathIndex].all[+el.dataset.conditionIndex].metric=value;else{const key=el.dataset.coreGroup==='building'?'buildingMetricIds':'activityMetricIds';draft[key]=[...(draft[key]||(key==='buildingMetricIds'?BUILDING_IDS:ACTIVITY_IDS))];draft[key][+el.dataset.coreIndex]=value;}stashContext();const section=document.querySelector('.demand-section');section.outerHTML=demandControls();updateImpact();refreshDecisionSection('ranking-weights');}
});
document.addEventListener('input',event=>{const el=event.target;if(el.hasAttribute('data-path-percentile')){draft.paths[+el.dataset.pathIndex].all[+el.dataset.conditionIndex].percentile=el.value===''?NaN:+el.value;queueImpact();}});

document.addEventListener('change',e=>{const el=e.target;if(el.name==='supply-mode'){draft=el.value==='relative'?YolkRelativeSupply.seedCriteria(draft,draft.supplyDenominatorId):{...draft,supplyMode:'count'};stashContext();refreshSupplyControls();document.querySelector('input[name="supply-mode"]:checked')?.focus()}if(el.id==='supply-denominator'){draft=YolkRelativeSupply.seedCriteria(draft,el.value);stashContext();refreshSupplyControls();document.querySelector('#supply-denominator')?.focus();notify(tr('ตั้งเกณฑ์แบบร่างใหม่ตามฐานตลาดที่เลือกแล้ว','Draft thresholds reseeded for the selected denominator'))}});
document.addEventListener("change",e=>{if(e.target.matches("[data-criterion],[data-weight-scope],[data-path-percentile],.criteria-range"))updateImpact()});
